def solve():
    working_m = []
    for m in range(1, 101):
        total_sum_m = m * (m + 1) // 2
        if total_sum_m % 6 != 0:
            continue

        S = total_sum_m // 6
        # dp[s1][s2] = True if there exist disjoint X, Y with sum(X)=s1 and sum(Y)=s2.
        # Since s1, s2 <= S, we can use a set of (s1, s2) pairs.
        dp = {(0, 0)}
        for i in range(1, m + 1):
            new_dp = set()
            for s1, s2 in dp:
                new_dp.add((s1, s2))
                if s1 + i <= S:
                    new_dp.add((s1 + i, s2))
                if s2 + i <= S:
                    new_dp.add((s1, s2 + i))
            dp = new_dp

        if (S, S) in dp:
            working_m.append(m)
    return working_m

print(solve())

def solve_check_order():
    m = 6
    S = 6*7//6
    # Order 1
    dp1 = [0] * (S + 1)
    dp1[0] = 1
    for i in range(1, m + 1):
        for s1 in range(S, -1, -1):
            dp1[s1] |= (dp1[s1] << i)
            if s1 >= i:
                dp1[s1] |= dp1[s1 - i]

    # Order 2
    dp2 = [0] * (S + 1)
    dp2[0] = 1
    for i in range(1, m + 1):
        for s1 in range(S, -1, -1):
            if s1 >= i:
                dp2[s1] |= dp2[s1 - i]
            dp2[s1] |= (dp2[s1] << i)

    print("Order 1:", [bin(x) for x in dp1])
    print("Order 2:", [bin(x) for x in dp2])

solve_check_order()
